  if len(num_str) <= 1:
    return False
  for i in range(len(num_str)-1,0,-1):
    if int(num_str[i]) > int(num_str[i-1]):
      for j in range(i,len(num_str)):
        if int(num_str[j]) > int(num_str[i-1]):
          num_str[i-1],num_str[j] = num_str[j],num_str[i-1]
          num_str[i:] = sorted(num_str[i:],reverse=True)
          return int(''.join(num_str))
  return False

