def get_maxgold(mine,n,m):
  dp = [[0]*m for _ in range(n)]
  for i in range(n-1,-1,-1):
    for j in range(m):
      if i==n-1:
        dp[i][j]=mine[i][j]
      elif j==0:
        dp[i][j]=mine[i][j]+max(dp[i+1][j],dp[i+1][j+1])
      elif j==m-1:
        dp[i][j]=mine[i][j]+max(dp[i+1][j],dp[i+1][j-1])
      else:
        dp[i][j]=mine[i][j]+max(dp[i+1][j],dp[i+1][j-1],dp[i+1][j+1])
  return max(dp[0])

