def max_profit(prices, k): 
  if k == 0 or len(prices) < 2: 
    return 0
  dp = [[0 for _ in range(k+1)] for _ in range(len(prices)+1)]
  for i in range(1,len(prices)+1):
    for j in range(1,k+1):
      dp[i][j] = max(dp[i-1][j], prices[i-1]-dp[i-1][j-1])
  return dp[-1][-1]

