def calculate_polygons(x,y,z,w,v):
  polygons = []
  for i in range(x):
    polygon = []
    for j in range(y):
      for k in range(z):
        for l in range(w):
          for m in range(v):
            polygon.append(((i * 2 - x + 1) / 2, (j * 2 - y + 1) / 2, (k * 2 - z + 1) / 2, (l * 2 - w + 1) / 2, (m * 2 - v + 1) / 2))
    polygons.append(polygon)
  return polygons

