def average_Odd(num):
  sum_odd = 0
  count_odd = 0
  while num > 0:
    if num % 2 != 0:
      sum_odd += num
      count_odd += 1
    num -= 1
  avg_odd = sum_odd / count_odd
  return avg_odd

from itertools import combinations
def no_of_subsequences(arr,k):
  count = 0
  for r in range(1,len(arr)+1):
    for combo in combinations(arr,r):
      product = 1
      for num in combo:
        product *= num
      if product < k:
        count += 1
  return count
